import{_ as a,a as t,c as o,ac as n}from"./chunks/framework.BSuaGltH.js";const p=JSON.parse('{"title":"第二册：实践与进步 · Lesson 19 Sold out","description":"学习 情态动词的意义与形式，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第二册：实践与进步 · Lesson 19 Sold out","description":"学习 情态动词的意义与形式，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第2册课时","summary":"学习 情态动词的意义与形式，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · Lesson 18 He often does this!","link":"/life/english/new-concept/book-2/unit-01/lesson-018"},"next":{"text":"第二册：实践与进步 · Lesson 20 One man in a boat","link":"/life/english/new-concept/book-2/unit-01/lesson-020"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · Lesson 18 He often does this!","link":"/life/english/new-concept/book-2/unit-01/lesson-018"},"next":{"text":"第二册：实践与进步 · Lesson 20 One man in a boat","link":"/life/english/new-concept/book-2/unit-01/lesson-020"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-01/lesson-019.md","filePath":"life/english/new-concept/book-2/unit-01/lesson-019.md"}'),l={name:"life/english/new-concept/book-2/unit-01/lesson-019.md"};function i(s,e,r,c,d,h){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="第二册-实践与进步-·-lesson-19-sold-out" tabindex="-1">第二册：实践与进步 · Lesson 19 Sold out <a class="header-anchor" href="#第二册-实践与进步-·-lesson-19-sold-out" aria-label="Permalink to &quot;第二册：实践与进步 · Lesson 19 Sold out&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-2/contents">本册目录</a> · <a href="/life/english/new-concept/book-2/unit-01/overview">单元 1</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>演出票售罄时仍有人因取消预订而得到座位；练习可能性、许可与已经发生的事实。本课的语言观察是：may become available 只说明有可能，不能改写为一定会有。could buy 在具体过去情景中不一定表示成功买到，成功结果可明确写 managed to buy。完成学习后，请写一段购票经历，区分当时的可能性与最终买到的数量。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>ticket</td><td>/ˈtɪkɪt/</td><td>n.</td><td>票</td><td>a return ticket</td></tr><tr><td>queue</td><td>/kjuː/</td><td>n.</td><td>队伍</td><td>join a queue</td></tr><tr><td>cancel</td><td>/ˈkænsəl/</td><td>v.</td><td>取消</td><td>cancel a booking</td></tr><tr><td>performance</td><td>/pəˈfɔːməns/</td><td>n.</td><td>演出</td><td>an evening performance</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>sell out — 售罄，活动或票可作主语</li><li>be in a queue — 在排队，queue 是可数名词</li></ul><h2 id="语法讲解-情态动词的意义与形式" tabindex="-1">语法讲解：情态动词的意义与形式 <a class="header-anchor" href="#语法讲解-情态动词的意义与形式" aria-label="Permalink to &quot;语法讲解：情态动词的意义与形式&quot;">​</a></h2><p>can、could、may、might、must 等情态动词后接动词原形，否定一般直接加 not，不需要 do。它们可能表示能力、许可、义务或推测，必须根据上下文区分；could 不总是过去时间，也能表示委婉请求或较弱的可能性。must not 表示禁止，do not have to 表示没有必要，二者意义完全不同。判断语气时先问说话人在提出要求还是评价证据。本课应用：may become available 只说明有可能，不能改写为一定会有。could buy 在具体过去情景中不一定表示成功买到，成功结果可明确写 managed to buy。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>Two seats may become available if someone cancels.</p></blockquote><p>如果有人取消预订，可能会空出两个座位。</p><p>may 修饰 become 表可能；if 从句 cancels 用现在时表达未来条件；someone 按单数处理。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>may to become 错误；情态动词后用原形，也不能把 may 解读成确定承诺。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>朗读 may become，may 不要误听成主语；对照 two seats 与 one spare ticket。可朗读本页原创示范并自行录音回听；本页不提供教材录音。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>Two seats may become available if someone cancels. I left my phone number at the desk. An hour later, the clerk called with one spare ticket.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>写一段购票经历，区分当时的可能性与最终买到的数量。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>第一句的组织方式：may 修饰 become 表可能；if 从句 cancels 用现在时表达未来条件；someone 按单数处理。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：may to become 错误；情态动词后用原形，也不能把 may 解读成确定承诺。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>选 cancel/cancels：if someone ___.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> cancels</p><p><strong>解析：</strong> 不定代词 someone 作主语时谓语按单数处理。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>工作人员最后提供了几张余票？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> One.</p><p><strong>解析：</strong> 第一句谈两座可能空出，最后实际只有一张。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>把“可能有余票”写成含 may 的句子。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> There may be a spare ticket.</p><p><strong>解析：</strong> may be 表可能存在，不保证一定有票。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：情态动词的意义与形式。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-2/unit-01/grammar">单元语法</a> · <a href="/life/english/new-concept/book-2/unit-01/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-2/unit-01/review">单元自测</a></p><p><a href="/life/english/new-concept/book-2/unit-01/lesson-018">上一课</a> · <a href="/life/english/new-concept/book-2/unit-01/overview">单元目录</a> · <a href="/life/english/new-concept/book-2/unit-01/lesson-020">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const m=a(l,[["render",i]]);export{p as __pageData,m as default};
